            NUISystem::CManager::GetInstance()->SendCommand(0x1a);
            break;
        case 6:
            NUISystem::CManager::GetInstance()->SendCommand(0x1c);
            break;
        case 7:
            NUISystem::CManager::GetInstance()->SendCommand(0x23);
            break;
        case 10:
            NUISystem::CManager::GetInstance()->SendCommand(0x1b);
            break;
